package io.github.yuroyami.kitepdf.core.render

import kotlin.io.encoding.Base64
import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * An image file draws upright by its EXIF orientation, as CSS Images 3's `image-orientation:
 * from-image` asks (#826). Each fixture is a 40 x 20 JPEG of four coloured quarters (red, green,
 * blue, yellow from the top left) with one of the eight orientations; the expected sizes and
 * quarters come from Pillow's ImageOps.exif_transpose.
 */
class ImageOrientationTest {

    private class Case(val orientation: Int, val width: Int, val height: Int, val quarters: List<Int>, val base64: String)

    private val colours = listOf(intArrayOf(255, 0, 0), intArrayOf(0, 255, 0), intArrayOf(0, 0, 255), intArrayOf(255, 255, 0))

    private val cases = listOf(
        Case(1, 40, 20, listOf(0,1,2,3), ""),
        Case(2, 40, 20, listOf(1,0,3,2), ""),
        Case(3, 40, 20, listOf(3,2,1,0), ""),
        Case(4, 40, 20, listOf(2,3,0,1), ""),
        Case(5, 20, 40, listOf(0,2,1,3), ""),
        Case(6, 20, 40, listOf(2,0,3,1), ""),
        Case(7, 20, 40, listOf(3,1,2,0), ""),
        Case(8, 20, 40, listOf(1,3,0,2), ""),
    )

    private fun nearest(rgba: ByteArray, w: Int, x: Int, y: Int): Int {
        val i = (y * w + x) * 4
        val px = IntArray(3) { rgba[i + it].toInt() and 0xFF }
        return colours.indices.minBy { c -> (0 until 3).sumOf { kotlin.math.abs(colours[c][it] - px[it]) } }
    }

    @Test
    fun every_orientation_draws_upright() {
        for (case in cases) {
            val bytes = Base64.decode(case.base64)
            val image = KiteImageData.fromEncodedImage(bytes)!!
            assertEquals(case.width to case.height, image.width to image.height, "orientation ${case.orientation}")
            assertEquals(case.orientation in 5..8, KiteImageData.swapsAxes(bytes))
            val rgba = image.toRgbaBytes()!!
            val w = image.width
            val h = image.height
            val seen = listOf(w / 4 to h / 4, 3 * w / 4 to h / 4, w / 4 to 3 * h / 4, 3 * w / 4 to 3 * h / 4).map { (x, y) -> nearest(rgba, w, x, y) }
            assertEquals(case.quarters, seen, "orientation ${case.orientation}")
            // Kept as stored when asked.
            val stored = KiteImageData.fromEncodedImage(bytes, applyOrientation = false)!!
            assertEquals(40 to 20, stored.width to stored.height)
        }
    }
}
